import React, {useState, useEffect} from 'react';
// @ts-ignore
import { useRegisterSW } from 'virtual:pwa-register/react';
import type {SelectChangeEvent} from '@mui/material/Select';
import {
    Box, Button, Card, CardContent, Container, Divider, FormControl, Grid,
    InputLabel, MenuItem, Paper, Select, Snackbar, Stack, Tab, Tabs, TextField, Typography
} from '@mui/material';

// --- Константы ---
const USERS = ['Евгения', 'Александра', 'Игорь'] as const;

const ALCOHOL_RATES = {
    'Пиво': 10,
    'Водка': 10,
    'Коктейль': 5,
    'Текила': 15
} as const;

const FOOD_ITEMS = [
    'Торт',
    'Коктейл безалкогольный',
    'Мороженое',
    'Другая сладость',
    'Мясо',
    'Рыба',
    'Картошка',
    'Сыр'
] as const;

const ALL_ITEMS = [...Object.keys(ALCOHOL_RATES), ...FOOD_ITEMS] as const;

// --- Типы ---
type User = typeof USERS[number];
type AllItem = typeof ALL_ITEMS[number];

interface Entry {
    id: number;
    user: User;
    item: AllItem;
    quantity: number;
    isAlcohol: boolean;
}

interface CustomTabPanelProps {
    children?: React.ReactNode;
    value: number;
    index: number;
}

// --- Вспомогательный компонент для вкладок ---
function CustomTabPanel({children, value, index}: CustomTabPanelProps): JSX.Element {
    return (
        <Box
            role="tabpanel"
            hidden={value !== index}
            id={`simple-tabpanel-${index}`}
            aria-labelledby={`simple-tab-${index}`}
            sx={{p: 3}}
        >
            {value === index && children}
        </Box>
    );
}

export function PartyTrackerApp(): JSX.Element {
    const [tabValue, setTabValue] = useState<number>(0);
    const { needRefresh, updateServiceWorker } = useRegisterSW();
    // Инициализация состояния из localStorage
    const [entries, setEntries] = useState<Entry[]>(() => {
        const saved = localStorage.getItem('party_entries');
        return saved ? JSON.parse(saved) : [];
    });

    // Форма добавления
    const [selectedUser, setSelectedUser] = useState<User>(USERS[0]);
    const [selectedItem, setSelectedItem] = useState<AllItem>(ALL_ITEMS[0]);
    const [quantity, setQuantity] = useState<number | string>(1);

    // Сохранение в localStorage при каждом изменении entries
    useEffect(() => {
        localStorage.setItem('party_entries', JSON.stringify(entries));
    }, [entries]);

    const handleTabChange = (_event: React.SyntheticEvent, newValue: number): void => {
        setTabValue(newValue);
    };

    const handleUserChange = (event: SelectChangeEvent<string>): void => {
        setSelectedUser(event.target.value as User);
    };

    const handleItemChange = (event: SelectChangeEvent<string>): void => {
        setSelectedItem(event.target.value as AllItem);
    };

    const handleQuantityChange = (event: React.ChangeEvent<HTMLInputElement>): void => {
        setQuantity(event.target.value);
    };

    const handleSubmit = (e: React.FormEvent<HTMLFormElement>): void => {
        e.preventDefault();
        const isAlcohol = Object.keys(ALCOHOL_RATES).includes(selectedItem);

        const newEntry: Entry = {
            id: Date.now(),
            user: selectedUser,
            item: selectedItem,
            quantity: Number(quantity),
            isAlcohol
        };

        setEntries([...entries, newEntry]);
        setQuantity(1);
    };

    const handleClearData = (): void => {
        if (window.confirm('Вы уверены, что хотите очистить всю историю?')) {
            setEntries([]);
        }
    };

    // --- Вычисления итогов ---
    const getUserStats = (userName: User): { alcoholScore: number; foodCount: number } => {
        const userEntries = entries.filter((e) => e.user === userName);
        let alcoholScore = 0;
        let foodCount = 0;

        userEntries.forEach((entry) => {
            if (entry.isAlcohol) {
                alcoholScore += entry.quantity * ALCOHOL_RATES[entry.item as keyof typeof ALCOHOL_RATES];
            } else {
                foodCount += entry.quantity;
            }
        });

        return {alcoholScore, foodCount};
    };

    return (
        <Container maxWidth="md" sx={{mt: 4}}>
            {needRefresh && (
                <Snackbar
                    open={true}
                    message="Доступна новая версия"
                    action={
                        <Button color="primary" onClick={updateServiceWorker}>
                            Обновить
                        </Button>
                    }
                />
            )}
            <Paper elevation={3}>
                {/* Хедер / Меню вкладок */}
                <Box sx={{borderBottom: 1, borderColor: 'divider'}}>
                    <Tabs value={tabValue} onChange={handleTabChange} centered>
                        <Tab label="Итого"/>
                        <Tab label="Занести данные"/>
                    </Tabs>
                </Box>

                {/* Вкладка 0: Итого */}
                <CustomTabPanel value={tabValue} index={0}>
                    <Typography variant="h5" gutterBottom align="center">
                        Итоговые результаты
                    </Typography>
                    <Grid container spacing={3} sx={{mt: 1}}>
                        {USERS.map((user) => {
                            const stats = getUserStats(user);
                            return (
                                <Grid item xs={12} sm={4} key={user}>
                                    <Card elevation={2}>
                                        <CardContent>
                                            <Typography variant="h6" color="primary" gutterBottom>
                                                {user}
                                            </Typography>
                                            <Divider sx={{mb: 2}}/>
                                            <Typography variant="body1">
                                                <strong>Выпито (условные мл):</strong> {stats.alcoholScore}
                                            </Typography>
                                            <Typography variant="body1" sx={{mt: 1}}>
                                                <strong>Съедено (порций/шт):</strong> {stats.foodCount}
                                            </Typography>
                                        </CardContent>
                                    </Card>
                                </Grid>
                            );
                        })}
                    </Grid>

                    {entries.length > 0 && (
                        <Box sx={{mt: 4, textAlign: 'center'}}>
                            <Button variant="outlined" color="error" onClick={handleClearData}>
                                Очистить все данные
                            </Button>
                        </Box>
                    )}
                </CustomTabPanel>

                {/* Вкладка 1: Занести данные */}
                <CustomTabPanel value={tabValue} index={1}>
                    <Typography variant="h5" gutterBottom align="center">
                        Добавление записи
                    </Typography>
                    <Box component="form" onSubmit={handleSubmit} sx={{maxWidth: 400, mx: 'auto', mt: 3}}>
                        <Stack spacing={3}>
                            <FormControl fullWidth>
                                <InputLabel id="user-select-label">Пользователь</InputLabel>
                                <Select
                                    labelId="user-select-label"
                                    value={selectedUser}
                                    label="Пользователь"
                                    onChange={handleUserChange}
                                >
                                    {USERS.map((u) => (
                                        <MenuItem key={u} value={u}>{u}</MenuItem>
                                    ))}
                                </Select>
                            </FormControl>

                            <FormControl fullWidth>
                                <InputLabel id="item-select-label">Напиток / Еда</InputLabel>
                                <Select
                                    labelId="item-select-label"
                                    value={selectedItem}
                                    label="Напиток / Еда"
                                    onChange={handleItemChange}
                                >
                                    {ALL_ITEMS.map((item) => (
                                        <MenuItem key={item} value={item}>{item}</MenuItem>
                                    ))}
                                </Select>
                            </FormControl>

                            <TextField
                                label="Количество (порций, шотов, кусков)"
                                type="number"
                                inputProps={{min: 1}}
                                value={quantity}
                                onChange={handleQuantityChange}
                                fullWidth
                                required
                            />

                            <Button type="submit" variant="contained" color="primary" size="large">
                                Записать
                            </Button>
                        </Stack>
                    </Box>
                </CustomTabPanel>
            </Paper>
        </Container>
    );
}

